L["Sync is on"] = "Sync attivo"
L["Sync is unavailable: the AceComm library didn't load."] = "Sync non disponibile: la libreria AceComm non è stata caricata."
L["Tabs"] = "Schede"
L["Takes"] = "Durata"
L["Teaches %s"] = "Insegna %s"
L["That nets"] = "Rende netto"
